function burst(x,y,color,n){for(let i=0;i<n;i++)particles.push({x,y,vx:(Math.random()-.5)*140,vy:-Math.random()*180,life:.45+Math.random()*.4,color,r:2+Math.random()*3})}
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function drawBackdrop(z){
 const r=realms[z],g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,r.sky[0]);g.addColorStop(1,r.sky[1]);ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
 // A hazy moon and long, layered silhouettes give each realm its own skyline.
 ctx.globalAlpha=.7;ctx.fillStyle=z===1?'#abd0c4':z===4?'#e1ddc7':'#ead4a2';ctx.beginPath();ctx.arc(754,112,38,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
 for(let layer=0;layer<3;layer++){
  const step=layer===0?215:layer===1?150:118,parallax=.13+layer*.13,offset=-(camera*parallax)%step;
  for(let i=-1;i<Math.ceil(W/step)+2;i++){
   let x=i*step+offset;const seed=Math.abs(i*47+z*131+layer*11),h=110+(seed%105),base=FLOOR-layer*20;
   ctx.fillStyle=layer===0?'#17242b55':layer===1?'#18252aaa':'#1a272dcc';
   ctx.beginPath();ctx.moveTo(x,base);ctx.lineTo(x,base-h+28);ctx.lineTo(x+step*.5,base-h);ctx.lineTo(x+step,base-h+25);ctx.lineTo(x+step,base);ctx.closePath();ctx.fill();
   // Mansard rooftops and narrow Parisian windows.
   if(layer>0){ctx.strokeStyle=z===2?'#df997455':'#d7c58c44';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x+step*.12,base-h+30);ctx.lineTo(x+step*.5,base-h);ctx.lineTo(x+step*.88,base-h+30);ctx.stroke();
    ctx.fillStyle=z===3?'#d3c98d66':'#e4c47c55';for(let wy=base-h+48;wy<base-25;wy+=25){ctx.fillRect(x+step*.28,wy,5,10);ctx.fillRect(x+step*.67,wy,5,10)}
   }
   if(seed%3===0){ctx.fillStyle='#19252d';ctx.fillRect(x+step*.45,base-h-29,step*.1,31);ctx.beginPath();ctx.moveTo(x+step*.39,base-h-26);ctx.lineTo(x+step*.5,base-h-52);ctx.lineTo(x+step*.61,base-h-26);ctx.fill()}
  }
 }
 // Distant suspended haze / drifting ash.
 ctx.globalAlpha=.13;ctx.fillStyle=r.accent;ctx.fillRect(0,244,W,115);ctx.globalAlpha=1;
}
function drawGround(z){const r=realms[z];ctx.fillStyle=r.ground;ctx.fillRect(0,FLOOR,W,H-FLOOR);ctx.fillStyle='#d5bc8055';ctx.fillRect(0,FLOOR,W,3);
 for(let x=-((camera*.6)%82);x<W+82;x+=82){ctx.fillStyle='#121f2355';ctx.fillRect(x,FLOOR+23,2,70);ctx.fillStyle='#d7bd7955';ctx.fillRect(x+20,FLOOR+20,22,2);ctx.fillRect(x+50,FLOOR+48,12,2)}
 // broken paving and little grass tufts
 for(let i=0;i<22;i++){let x=(i*127-camera*.75)%W;if(x<0)x+=W;ctx.fillStyle=i%2?'#172b2c':'#82907822';ctx.fillRect(x,FLOOR+5+(i%3)*7,18+(i%4)*4,2)}
}
function drawPlatform(o){const x=o.x-camera;if(x<-200||x>W+100)return;ctx.fillStyle='#182328';ctx.fillRect(x,o.y,o.w,o.h);ctx.fillStyle=realms[o.z].ground;ctx.fillRect(x,o.y,o.w,7);ctx.fillStyle=realms[o.z].accent+'88';ctx.fillRect(x,o.y,o.w,2);for(let xx=x+12;xx<x+o.w;xx+=31){ctx.strokeStyle='#c2b48333';ctx.beginPath();ctx.moveTo(xx,o.y+8);ctx.lineTo(xx-6,o.y+o.h);ctx.stroke()}}
function drawLantern(o){const x=o.x-camera;if(x<-60||x>W+60)return;ctx.strokeStyle='#a7966f';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,FLOOR);ctx.lineTo(x,o.y);ctx.stroke();ctx.fillStyle='#d5a55f';ctx.fillRect(x-5,o.y,10,14);ctx.fillStyle='#ffe0a0';ctx.globalAlpha=.85+.15*Math.sin(gameTime*4+x);ctx.beginPath();ctx.arc(x,o.y+7,3,0,Math.PI*2);ctx.fill();ctx.globalAlpha=.13;ctx.fillStyle='#ffe0a0';ctx.beginPath();ctx.arc(x,o.y+7,27,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
function drawSeal(o){if(o.got)return;const x=o.x-camera,y=o.y+Math.sin(gameTime*2.7+o.z)*8;if(x<-50||x>W+50)return;ctx.save();ctx.translate(x,y);ctx.rotate(gameTime*.35);ctx.shadowBlur=22;ctx.shadowColor=realms[o.z].accent;ctx.strokeStyle=realms[o.z].accent;ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,17,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.moveTo(0,-11);ctx.lineTo(9,0);ctx.lineTo(0,11);ctx.lineTo(-9,0);ctx.closePath();ctx.stroke();ctx.fillStyle='#f6dc9c';ctx.beginPath();ctx.arc(0,0,3,0,Math.PI*2);ctx.fill();ctx.restore()}
function drawNPC(o){const x=o.x-camera;if(x<-70||x>W+70)return;const bob=Math.sin(gameTime*2+o.x)*2;ctx.fillStyle='#171d25';ctx.beginPath();ctx.ellipse(x+o.w/2,FLOOR-2,18,5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=o.name==='King Louis'?'#d7bd7b':o.z===3?'#89a86e':'#8ca5a0';ctx.fillRect(x+5,FLOOR-37+bob,23,34);ctx.fillStyle='#d9b795';ctx.beginPath();ctx.arc(x+16,FLOOR-43+bob,10,0,Math.PI*2);ctx.fill();ctx.fillStyle='#384552';ctx.fillRect(x+7,FLOOR-46+bob,19,4);if(Math.abs(o.x-player.x)<110){ctx.fillStyle='#f0ddaa';ctx.font='10px DM Mono,monospace';ctx.textAlign='center';ctx.fillText('E',x+16,FLOOR-63+bob);ctx.fillStyle='#b9c3bc';ctx.font='8px DM Mono,monospace';ctx.fillText(o.name.toUpperCase(),x+16,FLOOR-75+bob)}}
function drawEnemy(o){if(!o.alive)return;const x=o.x-camera;if(x<-90||x>W+90)return;let bob=Math.sin(gameTime*4+o.x)*2;ctx.save();ctx.translate(x+o.w/2,FLOOR-o.h/2+bob);ctx.scale(o.dir,1);if(o.kind==='guardian'){ctx.fillStyle='#2a262d';ctx.beginPath();ctx.ellipse(0,0,25,27,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=realms[o.z].accent;ctx.fillRect(-18,-16,36,8);ctx.fillStyle='#f1d08b';ctx.fillRect(9,-7,4,4);ctx.fillStyle='#29262b';ctx.beginPath();ctx.moveTo(-20,-18);ctx.lineTo(-15,-34);ctx.lineTo(-8,-19);ctx.moveTo(8,-19);ctx.lineTo(17,-35);ctx.lineTo(18,-16);ctx.fill();ctx.fillStyle='#615663';ctx.fillRect(-20,17,40,9);ctx.fillStyle='#e07f6b';ctx.fillRect(-18,20,36*Math.max(0,o.hp/4),3)}else{ctx.fillStyle='#293335';ctx.beginPath();ctx.ellipse(0,3,19,17,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#9a6a67';ctx.beginPath();ctx.arc(0,-11,11,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d6c48c';ctx.fillRect(5,-13,4,3)}ctx.restore()}
function drawPlayer(){const p=player,x=p.x-camera,y=p.y,mid=x+p.w/2;ctx.save();if(p.invuln>0&&Math.floor(gameTime*20)%2===0)ctx.globalAlpha=.45;
 // short red traveling cape
 ctx.fillStyle='#9a3e48';ctx.beginPath();ctx.moveTo(mid-5,y+15);ctx.lineTo(mid-18-p.face*3,y+41);ctx.lineTo(mid+3,y+35);ctx.closePath();ctx.fill();ctx.fillStyle='#c6a65e';ctx.fillRect(mid-8,y+13,17,6);
 // plated frog body
 ctx.fillStyle='#6d9a79';ctx.beginPath();ctx.ellipse(mid,y+28,15,19,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#bdd18e';ctx.beginPath();ctx.ellipse(mid,y+33,9,10,0,0,Math.PI*2);ctx.fill();
 ctx.fillStyle='#79a782';ctx.beginPath();ctx.ellipse(mid-8,y+8,7,9,0,0,Math.PI*2);ctx.ellipse(mid+8,y+8,7,9,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f1dc99';ctx.beginPath();ctx.arc(mid-7,y+7,3,0,Math.PI*2);ctx.arc(mid+7,y+7,3,0,Math.PI*2);ctx.fill();ctx.fillStyle='#28302d';ctx.beginPath();ctx.arc(mid-7+p.face*1.5,y+7,1.3,0,Math.PI*2);ctx.arc(mid+7+p.face*1.5,y+7,1.3,0,Math.PI*2);ctx.fill();
 // helmet and little crest
 ctx.fillStyle='#a9a58b';ctx.beginPath();ctx.arc(mid,y+3,12,Math.PI,Math.PI*2);ctx.lineTo(mid+11,y+7);ctx.lineTo(mid-11,y+7);ctx.closePath();ctx.fill();ctx.fillStyle='#d4c492';ctx.fillRect(mid-10,y+5,20,3);ctx.fillStyle='#8c8a78';ctx.fillRect(mid-2,y-9,4,10);
 // sword swing arc / blade
 const sx=mid+p.face*15,sy=y+27;if(p.attack>0){ctx.strokeStyle='#f8e4a9';ctx.lineWidth=3;ctx.beginPath();ctx.arc(mid+p.face*7,sy,27,p.face===1?-1.35:Math.PI-1.35,p.face===1?1.15:Math.PI+1.15);ctx.stroke();ctx.fillStyle='#e6e2ce';ctx.save();ctx.translate(sx,sy);ctx.rotate(p.face*.8);ctx.fillRect(0,-2,31,4);ctx.restore()}else{ctx.strokeStyle='#d8d6c5';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(sx+p.face*16,sy-13);ctx.stroke();ctx.strokeStyle='#c49b58';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(sx-3,sy+2);ctx.lineTo(sx+4,sy-6);ctx.stroke()}
 ctx.fillStyle='#546e60';ctx.fillRect(mid-9,y+42,7,6);ctx.fillRect(mid+2,y+42,7,6);ctx.restore()}
function drawParticles(dt){for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=220*dt;p.life-=dt;if(p.life<=0){particles.splice(i,1);continue}ctx.globalAlpha=clamp(p.life*2,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x-camera,p.y,p.r,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1}
function drawWorld(){const z=clamp(Math.floor(player.x/ZONE),0,4);drawBackdrop(z);drawGround(z);
 for(const o of worldObjects){if(o.type==='platform')drawPlatform(o);else if(o.type==='lantern')drawLantern(o);else if(o.type==='seal')drawSeal(o)}
 for(const o of worldObjects)if(o.type==='npc')drawNPC(o);
 for(const o of worldObjects)if(o.type==='enemy')drawEnemy(o);
 drawPlayer();drawParticles(0); // particle simulation occurs in update
 // Foreground mist and border vignette
 const fog=ctx.createLinearGradient(0,420,0,535);fog.addColorStop(0,'#a6b0a022');fog.addColorStop(1,'#a6b0a000');ctx.fillStyle=fog;ctx.fillRect(0,420,W,115);
 const v=ctx.createRadialGradient(W/2,H/2,170,W/2,H/2,590);v.addColorStop(0,'#00000000');v.addColorStop(1,'#090d14aa');ctx.fillStyle=v;ctx.fillRect(0,0,W,H);
}

